const raceDone = (c, r) => { if(BUL.note) return false; const d = raceStart(c, r); return !!d && d <= new Date(); };
const raceRes = (c, r) => (BUL.res[c] && BUL.res[c][r]) || null;
// ---- Koşu filmi bağlantıları (TJK sonuç sayfasından okunur, cihazda saklanır) ----
const VID = {}, _vidLoaded = {}, _vidTried = {};
function vidLoad(iso){
  if(_vidLoaded[iso]) return; _vidLoaded[iso] = 1;
  try{ Object.assign(VID, JSON.parse(localStorage.getItem('gs_vid_' + iso) || '{}')); }catch(e){}
}
function vidSet(iso, sid, map){
  vidLoad(iso);
  let ch = false;
  Object.keys(map || {}).forEach(n => { const k = iso + '|' + sid + '|' + n; if(map[n] && VID[k] !== map[n]){ VID[k] = map[n]; ch = true; } });
  if(!ch) return;
  try{
    const o = {}; Object.keys(VID).forEach(k => { if(k.indexOf(iso + '|') === 0) o[k] = VID[k]; });
    localStorage.setItem('gs_vid_' + iso, JSON.stringify(o));
  }catch(e){}
}
function vidGet(c, r){
  const i = BUL.ids[c]; if(!i) return '';
  vidLoad(viewIso);
  const v = VID[viewIso + '|' + i.id + '|' + r] || '';
  const kk = v.match(/YarisVideoKosu\/Kosu\?KosuKodu=(-?\d+)/i);
  return kk ? 'https://www.tjk.org/TR/yarissever/Info/YarisVideoKosu/Kosu?KosuKodu=' + kk[1] : v;
}
const vkey = (c, r) => { const i = BUL.ids[c]; return i ? viewIso + '|' + i.id + '|' + r : null; };
const MP4 = {}; let _mp4Iso = '';
function mp4Load(){ if(_mp4Iso === viewIso) return; _mp4Iso = viewIso; try{ Object.assign(MP4, JSON.parse(localStorage.getItem('gs_mp4_' + viewIso) || '{}')); }catch(e){} }
function mp4Set(k, u){
  MP4[k] = u;
  try{ const o = {}; Object.keys(MP4).forEach(x => { if(x.indexOf(viewIso + '|') === 0) o[x] = MP4[x]; }); localStorage.setItem('gs_mp4_' + viewIso, JSON.stringify(o)); }catch(e){}
}
function tjkLink(c){
  const i = BUL.ids[c]; if(!i) return '';
  const [y, m, d] = viewIso.split('-');
  const u = 'https://www.tjk.org/TR/yarissever/Info/Sehir/GunlukYarisSonuclari?SehirId=' + i.id + '&QueryParameter_Tarih=' + encodeURIComponent(d + '/' + m + '/' + y) + '&SehirAdi=' + encodeURIComponent(i.adi) + '&Era=' + (viewIso < TJK.bugunIso() ? 'yesterday' : 'today');
  return `<a class="rp-vid" href="${esc(u)}" target="_blank" rel="noopener">▶ TJK'da koşu videosunu izle</a>`;
}
let _vmH = false;
function vidOpen(btn){ const c = btn.dataset.c, r = +btn.dataset.r, k = vkey(c, r); if(k && MP4[k]) vidModal(c, r, k); }
// Açılır pencere: liste yeniden çizilmez, yalnızca tek bir video öğesi kurulur; kapanınca tamamen kaldırılır
function vidModal(c, r, k){
  vidCloseModal(true);
  const i = BUL.ids[c] || {}, [y, m, d] = viewIso.split('-');
  const o = document.createElement('div'); o.id = 'vm'; o.className = 'vm vm-wide';
  const res = (raceRes(c, r) || []).slice(0, 4), hs = horsesFor(c, r);
  const rh = res.map((no, i) => { const h = hs.find(x => x.no === no) || {name: ''}, g = gnyOf(c, r, no); return `<div class="r${i + 1}"><i class="rk">${i + 1}</i>${sc(no)}<div class="nm"><span>${esc(h.name)}</span><small>${['Kazandı', '2. oldu', '3. oldu', '4. oldu'][i]}</small></div>${g ? '<em>Ganyan ' + esc(g) + '</em>' : ''}</div>`; }).join('');
  o.innerHTML = `<div class="vm-s" role="dialog" aria-modal="true">
    <div class="vm-h"><span class="vm-ch">${r}</span><div class="vm-t">${esc(i.adi || c)} · ${r}. Koşu<small>Koşu filmi · ${d}.${m}.${y}</small></div><button type="button" class="vm-x" aria-label="Kapat" onclick="vidCloseModal()"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg></button></div>
    <video controls playsinline autoplay preload="metadata" controlsList="nodownload" src="${esc(MP4[k])}"></video>
    ${rh ? '<div class="vm-rt">Koşu sonucu</div><div class="vm-res">' + rh + '</div>' : ''}
    <div class="vm-b">
      <button type="button" onclick="vidSeek(-10)">↺ 10</button>
      <button type="button" onclick="vidSeek(10)">10 ↻</button>
      <span class="sp"></span>
      <div class="vm-seg"><button type="button" onclick="vidSpeed(this,0.5)">0.5x</button><button type="button" class="on" onclick="vidSpeed(this,1)">1x</button><button type="button" onclick="vidSpeed(this,2)">2x</button></div>
      <button type="button" class="vm-fs" onclick="vidFull()" aria-label="Tam ekran"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg></button>
    </div></div>`;
  o.addEventListener('click', e => { if(e.target === o) vidCloseModal(); });
  document.body.appendChild(o);
  document.body.style.overflow = 'hidden';
  if(!_vmH){ try{ history.pushState({vm: 1}, ''); _vmH = true; }catch(e){} }
}
function vidCloseModal(silent){
  if(window._lvT){ clearInterval(window._lvT); window._lvT = null; }
  if(window._hls){ try{ window._hls.destroy(); }catch(e){} window._hls = null; }
  const o = $('vm'); if(!o) return;
  const v = o.querySelector('video');
  try{ v.pause(); v.removeAttribute('src'); v.load(); }catch(e){}
  o.remove(); document.body.style.overflow = '';
  if(!silent && _vmH){ _vmH = false; try{ history.back(); }catch(e){} }
}
window.addEventListener('popstate', () => { if($('vm')){ _vmH = false; vidCloseModal(true); } });
document.addEventListener('keydown', e => { if(e.key === 'Escape') vidCloseModal(); });
// ---- CANLI YAYIN (TJK / Tay TV, HLS) ----
const LIVE_URL = 'https://tjktv-live.tjk.org/taytv/taytv.m3u8';
function liveMsg(t){ const e = $('vm-msg'); if(e){ e.textContent = t; e.style.display = t ? 'block' : 'none'; } }
function liveHlsYukle(){
  return new Promise((ok, no) => {
    if(window.Hls) return ok(window.Hls);
    const sc = document.createElement('script'); sc.src = 'https://cdn.jsdelivr.net/npm/hls.js@1.5.17/dist/hls.min.js';
    sc.onload = () => ok(window.Hls); sc.onerror = () => no(new Error('hls.js yüklenemedi'));
    document.head.appendChild(sc);
  });
}
async function liveOpen(){
  vidCloseModal(true);
  const o = document.createElement('div'); o.id = 'vm'; o.className = 'vm vm-live';
  o.innerHTML = `<div class="vm-s" role="dialog" aria-modal="true">
    <div class="vm-h"><span class="lv-chip" id="lv-chip"><i></i><span id="lv-ct">CANLI</span></span><div class="vm-t">Tay TV<small>TJK yarış yayını</small></div><button type="button" class="vm-x" aria-label="Kapat" onclick="vidCloseModal()"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg></button></div>
    <video controls playsinline autoplay></video>
    <div class="vm-msg" id="vm-msg"></div>
    <div class="lv-panel">
      <div class="lv-row">
        <button type="button" class="lv-live" onclick="liveEdge()"><i></i>Canlıya dön</button>
        <button type="button" class="lv-full" onclick="vidFull()" aria-label="Tam ekran"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg>Tam ekran</button>
      </div>
    </div></div>`;
  o.addEventListener('click', e => { if(e.target === o) vidCloseModal(); });
  document.body.appendChild(o);
  document.body.style.overflow = 'hidden';
  if(!_vmH){ try{ history.pushState({vm: 1}, ''); _vmH = true; }catch(e){} }
  const v = o.querySelector('video');
  if(window._lvT) clearInterval(window._lvT);
  window._lvT = setInterval(liveTick, 1000);
  const native = () => { v.src = LIVE_URL; v.play().catch(() => {}); };
  v.addEventListener('error', () => liveMsg('Yayın açılamadı. TJK yayını şu an kapalı olabilir ya da bu bağlantıyı engelliyor.'));
  v.addEventListener('playing', () => liveMsg(''));
  try{
    const Hls = await liveHlsYukle();
    if(!$('vm')) return;
    if(Hls && Hls.isSupported()){
      const h = new Hls({maxBufferLength: 20, liveSyncDurationCount: 3});
      window._hls = h;
      h.on(Hls.Events.ERROR, (ev, d) => { if(d && d.fatal){ try{ h.destroy(); }catch(e){} window._hls = null; native(); } });   // hls.js olmazsa tarayıcının kendi oynatıcısı
      h.loadSource(LIVE_URL); h.attachMedia(v);
      v.play().catch(() => {});
    } else native();
  }catch(e){ native(); }
}
function liveTick(){
  const v = vidV(), c = $('lv-chip'), t = $('lv-ct'); if(!v || !c || !t) return;
  const sk = v.seekable; if(!sk || !sk.length) return;
  const lag = sk.end(sk.length - 1) - v.currentTime;
  if(lag > 20){ const m = Math.floor(lag / 60), sn = Math.floor(lag % 60); c.classList.add('late'); t.textContent = 'GERİDE ' + m + ':' + String(sn).padStart(2, '0'); }
  else { c.classList.remove('late'); t.textContent = 'CANLI'; }
}
function liveEdge(){ const v = vidV(); if(!v) return; try{ if(v.seekable && v.seekable.length) v.currentTime = v.seekable.end(v.seekable.length - 1); v.play(); }catch(e){} }
const vidV = () => { const o = $('vm'); return o ? o.querySelector('video') : null; };
function vidSeek(dt){ const v = vidV(); if(v) v.currentTime = Math.max(0, Math.min((v.duration || 1e9), v.currentTime + dt)); }
function vidSpeed(btn, x){ const v = vidV(); if(v) v.playbackRate = x; btn.parentNode.querySelectorAll('button').forEach(b => b.classList.toggle('on', b === btn)); }
function vidFull(){
  const v = vidV(); if(!v) return;
  const f = v.requestFullscreen || v.webkitRequestFullscreen || v.webkitEnterFullscreen; if(!f) return;
  try{ const p = f.call(v); if(p && p.then) p.then(() => { try{ screen.orientation.lock('landscape').catch(() => {}); }catch(e){} }).catch(() => {}); }catch(e){}
}
document.addEventListener('fullscreenchange', () => { if(!document.fullscreenElement){ try{ screen.orientation.unlock(); }catch(e){} } });
const vidBtn = (c, r) => {
  const k = vkey(c, r); if(!k) return '';
  mp4Load();
  if(MP4[k]) return `<button type="button" class="rp-vid" data-c="${esc(c)}" data-r="${r}" onclick="vidOpen(this)">▶ Koşu videosunu izle</button>`;
  if(vidGet(c, r)) return `<button type="button" class="rp-vid" data-c="${esc(c)}" data-r="${r}" onclick="vidPlay(this)">▶ Koşu videosunu izle</button>`;
  return `<button type="button" class="rp-vid" data-c="${esc(c)}" data-r="${r}" onclick="vidFind(this)">▶ Koşu videosunu izle</button>`;
};
// Düğmeye basınca: koşunun TJK video sayfasından mp4 adresini oku, videoyu uygulamada oynat
async function vidPlay(btn){
  const c = btn.dataset.c, r = +btn.dataset.r, k = vkey(c, r), t0 = btn.textContent;
  btn.disabled = true; btn.textContent = 'Video yükleniyor…';
  const vu = vidGet(c, r);
  let html = '', hata = '';
  try{
    if(/\.mp4(\?|$)/i.test(vu)){ mp4Set(k, vu); btn.disabled = false; btn.textContent = t0; vidModal(c, r, k); return; }
    window.__tjkFresh = true;
    try{ html = await TJK.fetchHtml(vu); } finally { window.__tjkFresh = false; }
    const m = html.match(/(?:https?:)?\/\/video-cdn\.tjk\.org\/videoftp\/[^"'\s<>\\]+?\.mp4/i) || html.match(/videoftp\/\d{4}\/\d{2}\/[\w-]+\.mp4/i);
    if(!m) throw new Error('mp4 sayfada yok');
    let u = m[0];
    if(u.indexOf('//') === 0) u = 'https:' + u; else if(!/^https?:/i.test(u)) u = 'https://video-cdn.tjk.org/' + u;
    mp4Set(k, u); btn.disabled = false; btn.textContent = t0; vidModal(c, r, k);
    return;
  }catch(e){ hata = (e && e.message) ? e.message : String(e); }
  // Video adresi okunamadı (TJK geç yüklüyor olabilir): hata metni yerine sade bilgi göster
  btn.disabled = false; btn.textContent = t0;
  vidYok(btn, vu, hata);
}
// TJK videoyu henüz yüklemediyse kısa bilgi: "şu an hazır değil"
function vidYok(btn, u, why){
  const old = btn.parentNode.querySelector('.vid-dbg'); if(old) old.remove();
  btn.insertAdjacentHTML('afterend', '<div class="vid-dbg" style="margin:8px 2px;padding:10px 12px;border-radius:12px;font-size:13.5px;font-weight:800;color:#B45309;background:rgba(245,158,11,.16);border:1px solid rgba(245,158,11,.5)">⏳ Video henüz hazır değil. Biraz sonra tekrar dene.</div>');
}
// Video adresi kayıtlı değilse: sonuç sayfasını yeniden tara; bulursa oynat, bulamazsa sayfadaki ilgili HTML parçalarını göster
async function vidFind(btn, tekrar){
  const c = btn.dataset.c, r = +btn.dataset.r, i = BUL.ids[c], t0 = btn.textContent;
  if(!i) return;
  btn.disabled = true; btn.textContent = 'Video aranıyor…';
  const [y, m, d] = viewIso.split('-');
  const u = 'https://www.tjk.org/TR/yarissever/Info/Sehir/GunlukYarisSonuclari?SehirId=' + i.id + '&QueryParameter_Tarih=' + encodeURIComponent(d + '/' + m + '/' + y) + '&SehirAdi=' + encodeURIComponent(i.adi) + '&Era=' + (viewIso < TJK.bugunIso() ? 'yesterday' : 'today');
  try{
    window.__tjkFresh = true;
    try{ await TJK.sonuclariGetir(i.id, i.adi, viewIso, raceList(c)); } finally { window.__tjkFresh = false; }
    if(vidGet(c, r) && !tekrar){ btn.disabled = false; btn.textContent = t0; return vidPlay(btn); }
    if(vidGet(c, r) && tekrar){ btn.disabled = false; btn.textContent = t0; return; }
    btn.disabled = false; btn.textContent = t0;
    vidYok(btn, u);
  }catch(e){
    btn.disabled = false; btn.textContent = t0;
    showToast('TJK sayfasına ulaşılamadı: ' + (e && e.message ? e.message : e));
  }
}
function resPanelHtml(c, r, kisa){
  if(!raceDone(c, r)) return '';
  const res = raceRes(c, r);
  if(!res) return kisa ? '<div class="rp wait"><b>Sonuç alınıyor…</b></div>' : '<div class="rp wait"><b>Koşu saati geldi · ' + (admTest() ? 'admin için seçim açık' : 'seçime kapalı') + '</b><small>Sonuç alınıyor…</small></div>';
  const hs = horsesFor(c, r), lab = ['Kazandı', '2. oldu', '3. oldu', '4. oldu'];
  const bh = (BUL.bahis[c] && BUL.bahis[c][r]) || [];
  const bhHtml = bh.length ? '<div class="rp-b"><div class="rp-bh">Bahis ödemeleri</div>' + bh.map(x => `<div class="rp-br"><span>${esc(x.tur)}</span><em>${esc(x.detay)}</em><b>${esc(x.tutar)} ₺</b></div>`).join('') + '</div>' : (kisa ? '<div class="rp-b"><div class="rp-bh">Bahis ödemeleri</div><div class="rp-none">Henüz yayınlanmadı</div></div>' : '');
  return '<div class="rp"><div class="rp-h">Koşu bitti · ' + (admTest() ? 'admin için seçim açık' : 'seçime kapalı') + '</div>' + res.slice(0, 4).map((no, i) => {
    const h = hs.find(x => x.no === no) || {name: '', jockey: ''};
    return `<div class="rp-r p${i+1}">${sc(no)}<div class="hn"><b>${esc(h.name)}</b><small>${esc(h.jockey)}</small></div><span class="rk">${lab[i]}${gnyOf(c, r, no) ? gnyPill(gnyOf(c, r, no), 'Ganyan') : ''}</span></div>`;
  }).join('') + bhHtml + vidBtn(c, r) + '</div>';
}
const resKey = () => 'gs_sonuc_v8_' + viewIso;
// ---- SONUÇ KONTROLÜ ----
// Koşu saatinden +3 dk: ilk sonuç (gelene kadar 10 sn'de bir). +4 dk: ödemeler (gelene kadar 10 sn'de bir). +8 dk'dan sonra (TJK geç verirse) dakikada bir. +40 dk: tek seferlik son kontrol.
const SONUC_ILK = 90000, SONUC_KONTROL = 4 * 60000, SONUC_YAVAS = 20 * 60000, SONUC_FINAL = 40 * 60000, SONUC_SON = 3 * 3600000, SONUC_ARA = 5000;   // SONUC_SON: sonuç hiç gelmezse 3 saat sonra vazgeç (iptal koşu)
//   // ilk 20 dk (SONUC_YAVAS) boyunca 5 sn'de bir, sonra dakikada bir
const idleRun = fn => (window.requestIdleCallback ? requestIdleCallback(fn, {timeout: 1500}) : setTimeout(fn, 50));
// Sayfayı titretmeden yeniden çiz: kaydırma korunur, kullanıcı yazıyorsa bekler, tek seferde birleştirir
function softRefresh(){
  if(softRefresh.p) return; softRefresh.p = true;
  const run = () => {
    const a = document.activeElement;
    if(a && /^(TEXTAREA|INPUT)$/.test(a.tagName)) return setTimeout(run, 3000);
    if(Date.now() - _lastTouch < 700) return setTimeout(run, 400);
    if(document.getElementById('vm')) return setTimeout(run, 2500);   // video penceresi açıkken liste yenilenmesin   // parmak/kaydırma bitmeden çizme
    const y = window.scrollY;
    softRefresh.p = false;
    rerender();
    if(Math.abs(window.scrollY - y) > 1) window.scrollTo({top: y, behavior: 'instant'});
  };
  idleRun(() => requestAnimationFrame(run));
}
function saveRes(){ try{ localStorage.setItem(resKey(), JSON.stringify({res: BUL.res, gny: BUL.gny, bahis: BUL.bahis, chk: BUL.chk})); }catch(e){} try{ setTimeout(arcToday, 1500); }catch(e){} }
async function pollSonuc(force){
  if(pollSonuc.busy || BUL.note || document.hidden) return;
  if(Date.now() < (pollSonuc.pause || 0)) return;   // 429/403 alındı: 5 dk hiç sorma
  pollSonuc.busy = true; pollSonuc.last = pollSonuc.last || {};
  let changed = false;
  try{
    await Promise.all(CITIES.map(async c => {   // tüm hipodromlar aynı anda
      const info = BUL.ids[c]; if(!info) return;
      const now = Date.now();
      const due = raceList(c).filter(k => {
        const no = +k.no, d = raceStart(c, no); if(!d) return false;
        const age = now - d.getTime();
        const ck = (BUL.chk[c] && BUL.chk[c][no]) || 0;                             // 0: bekliyor, 1: ödemeler tamam, 2: son kontrol yapıldı
        // Eski koşular (önbellek silinmiş / site geç açılmış): sonuç yoksa hemen çek. TJK'da hiç sonuç yayınlanmayan koşu için en fazla 3 deneme
        pollSonuc.tried = pollSonuc.tried || {};
        if(age > SONUC_SON && !raceRes(c, no)){   // 3 saatten eski, sonucu hâlâ yok: en çok 3 deneme
          const tk = c + '|' + no;
          return (pollSonuc.tried[tk] || 0) < 3;
        }
        if(!raceRes(c, no)) return age >= SONUC_ILK;                                // 1) ilk sonuç: +3 dk, 30 sn'de bir, gelene kadar
        // Video bağlantısını TJK sonradan ekler: sonuç + ödeme tamam olsa da video gelene kadar (en çok 90 dk) dakikada bir tekrar bak
        if(raceRes(c, no) && age >= SONUC_KONTROL && age < 90 * 60000 && !vidGet(c, no) && !MP4[vkey(c, no)]) return true;
        if(ck >= 2) return false;
        if(age >= SONUC_FINAL) return true;                                         // 3) son kontrol: +40 dk, tek sefer
        return ck === 0 && age >= SONUC_ILK;                                    // 2) ödemeler: +4 dk, 30 sn'de bir, gelene kadar
      });
      if(!due.length) return;
      pollSonuc.fail = pollSonuc.fail || {};
      let bekle = Math.min(60000, SONUC_ARA * Math.pow(2, pollSonuc.fail[c] || 0));   // hata alırsa 10→20→40→60 sn
      // Kademeli aralık (en yeni bekleyen koşuya göre; worker önbelleksiz varsayıldı): 1.5-5 dk 5 sn, 10 dk'ya kadar 10 sn, 20 dk'ya kadar 20 sn, 40 dk'ya kadar 30 sn, sonrası 60 sn
      const yas = Math.min(...due.map(k => now - raceStart(c, +k.no).getTime()));
      bekle = Math.max(bekle, yas < 5 * 60000 ? SONUC_ARA : yas < 10 * 60000 ? 10000 : yas < SONUC_YAVAS ? 20000 : yas < SONUC_FINAL ? 30000 : 60000);
      if(due.every(k => raceRes(c, +k.no) && now - raceStart(c, +k.no).getTime() >= SONUC_YAVAS)) bekle = Math.max(bekle, 60000);   // sadece video bekleyenler 20 dk sonra dakikada bir; sonucu gelmeyen koşu 5 sn'de bir sorulur   // 8 dk'dan eski bekleyenler: dakikada bir (worker'ı zorlamasın)
      if(!force && now - (pollSonuc.last[c] || 0) < bekle - 300) return;   // 300 ms tolerans: 5 sn'lik ritim kaymasın
      pollSonuc.last[c] = now;
      try{
        const iso0 = viewIso;
        const vOnce = due.map(k => !!vidGet(c, +k.no)).join();
        window.__tjkFresh = true;
        let r; try{ r = await TJK.sonuclariGetir(info.id, info.adi, iso0, raceList(c)); } finally { window.__tjkFresh = false; }
        if(iso0 !== viewIso) return;   // tarih değişti, eski veriyi yazma
        if(vOnce !== due.map(k => !!vidGet(c, +k.no)).join()) changed = true;   // yeni video bağlantısı geldi: düğmeyi güncelle
        pollSonuc.fail[c] = 0;
        due.forEach(k => { if(Date.now() - raceStart(c, +k.no).getTime() > SONUC_SON && !raceRes(c, +k.no)){ const tk = c + '|' + k.no; pollSonuc.tried[tk] = (pollSonuc.tried[tk] || 0) + 1; } });
        BUL.res[c] = BUL.res[c] || {}; BUL.gny[c] = BUL.gny[c] || {}; BUL.bahis[c] = BUL.bahis[c] || {}; BUL.chk[c] = BUL.chk[c] || {};
        due.forEach(k => {
          const no = +k.no; if(!r.sira[no]) return;
          const age = Date.now() - raceStart(c, no).getTime();
          const yeniB = (r.bahis && r.bahis[no]) || [];
          const eski = JSON.stringify([BUL.res[c][no], BUL.gny[c][no], BUL.bahis[c][no]]);
          BUL.res[c][no] = r.sira[no];
          BUL.gny[c][no] = r.gny[no] || {};
          if(yeniB.length || !BUL.bahis[c][no]) BUL.bahis[c][no] = yeniB;
          // ödemeler geldiyse tekrar denenmez; 8. dk'daki son kontrol tek sefer yapılır
          if(age >= SONUC_FINAL) BUL.chk[c][no] = 2;
          else if(age >= SONUC_KONTROL && (BUL.bahis[c][no] || []).length) BUL.chk[c][no] = 2;
          if(eski !== JSON.stringify([BUL.res[c][no], BUL.gny[c][no], BUL.bahis[c][no]])) changed = true;
        });
      }catch(e){ pollSonuc.fail[c] = Math.min(3, (pollSonuc.fail[c] || 0) + 1); if(/HTTP (429|403)/.test(String(e && e.message))) pollSonuc.pause = Date.now() + 5 * 60000; }
    }));
  } finally { pollSonuc.busy = false; }
  if(changed){ saveRes(); if(force) rerender(); else softRefresh(); }   // ilk açılışta bekletmeden çiz
}
// ---- AÇILIŞTA ÖDEMELER: eksik bahis ödemelerini hemen, arka arkaya en fazla 5 kez çek ----
const odemeEksik = (c, no) => {
  const d = raceStart(c, no); if(!d) return false;
  if(Date.now() - d.getTime() < SONUC_KONTROL) return false;            // koşu daha yeni bitti, ödeme yayınlanmamış olabilir
  const b = BUL.bahis[c] && BUL.bahis[c][no];
  return !raceRes(c, no) || !(b && b.length);
};
const _odemeIso = {};
async function odemeSerisi(){
  const iso = viewIso;
  if(_odemeIso[iso] || odemeSerisi.run || BUL.note || !CITIES.length) return;
  if(document.hidden) return;                                            // ekran açılınca tekrar denenir
  odemeSerisi.run = true;
  try{
    for(let t = 0; pollSonuc.busy && t < 100; t++) await new Promise(r => setTimeout(r, 300));   // normal sorgu bitsin, aynı isteği ikiletme
    for(let deneme = 1; deneme <= 5; deneme++){
      if(iso !== viewIso) return;
      const hedef = CITIES.filter(c => BUL.ids[c] && raceList(c).some(k => odemeEksik(c, +k.no)));
      if(!hedef.length) break;
      let degisti = false;
      await Promise.all(hedef.map(async c => {
        try{
          const info = BUL.ids[c];
          const r = await TJK.sonuclariGetir(info.id, info.adi, iso, raceList(c));
          if(iso !== viewIso) return;
          BUL.res[c] = BUL.res[c] || {}; BUL.gny[c] = BUL.gny[c] || {}; BUL.bahis[c] = BUL.bahis[c] || {}; BUL.chk[c] = BUL.chk[c] || {};
          raceList(c).forEach(k => {
            const no = +k.no;
            if(!odemeEksik(c, no) || !r.sira[no]) return;
            const age = Date.now() - raceStart(c, no).getTime();
            const yeniB = (r.bahis && r.bahis[no]) || [];
            const eski = JSON.stringify([BUL.res[c][no], BUL.gny[c][no], BUL.bahis[c][no]]);
            BUL.res[c][no] = r.sira[no];
            BUL.gny[c][no] = r.gny[no] || {};
            if(yeniB.length || !BUL.bahis[c][no]) BUL.bahis[c][no] = yeniB;
            if(age >= SONUC_FINAL) BUL.chk[c][no] = 2;
            else if((BUL.bahis[c][no] || []).length) BUL.chk[c][no] = 2;
            if(eski !== JSON.stringify([BUL.res[c][no], BUL.gny[c][no], BUL.bahis[c][no]])) degisti = true;
          });
        }catch(e){}
      }));
      if(iso !== viewIso) return;
      if(degisti){ saveRes(); softRefresh(); }
      if(!CITIES.some(c => raceList(c).some(k => odemeEksik(c, +k.no)))) break;   // hepsi geldi
      if(deneme < 5) await new Promise(r => setTimeout(r, 1200));
    }
    _odemeIso[iso] = true;
  } finally { odemeSerisi.run = false; }
}
// ---- KOŞUYA GEÇİNCE: o koşunun sonucu / bahis ödemeleri eksikse hemen çek ----
const _kosuCek = {};
async function kosuSonucCek(c, r){
  if(!c || !r || BUL.note || !BUL.ids[c] || !raceDone(c, r)) return;
  const b = BUL.bahis[c] && BUL.bahis[c][r];
  const tk = c + '|' + r, now = Date.now();
  if(raceRes(c, r) && b && b.length && (vidGet(c, r) || _vidTried[viewIso + tk])) return;               // zaten tamam
  if(_kosuCek[tk] && (_kosuCek[tk].busy || now - _kosuCek[tk].t < 8000)) return;   // 8 sn'de bir
  _kosuCek[tk] = {busy: true, t: now};
  const iso = viewIso;
  try{
    for(let t = 0; pollSonuc.busy && t < 40; t++) await new Promise(x => setTimeout(x, 250));   // arka plan sorgusu bitsin
    const info = BUL.ids[c];
    const v0 = vidGet(c, r);
    const res = await TJK.sonuclariGetir(info.id, info.adi, iso, raceList(c));
    _vidTried[iso + tk] = 1;
    if(iso === viewIso && vidGet(c, r) !== v0) softRefresh();
    if(iso !== viewIso || !res.sira[r]) return;
    BUL.res[c] = BUL.res[c] || {}; BUL.gny[c] = BUL.gny[c] || {}; BUL.bahis[c] = BUL.bahis[c] || {}; BUL.chk[c] = BUL.chk[c] || {};
    const eski = JSON.stringify([BUL.res[c][r], BUL.gny[c][r], BUL.bahis[c][r]]);
    const yeniB = (res.bahis && res.bahis[r]) || [];
    BUL.res[c][r] = res.sira[r];
    BUL.gny[c][r] = res.gny[r] || {};
    if(yeniB.length || !BUL.bahis[c][r]) BUL.bahis[c][r] = yeniB;
    if(yeniB.length && !BUL.chk[c][r]) BUL.chk[c][r] = 2;
    if(eski !== JSON.stringify([BUL.res[c][r], BUL.gny[c][r], BUL.bahis[c][r]])){ saveRes(); softRefresh(); }
  }catch(e){}
  finally{ _kosuCek[tk].busy = false; _kosuCek[tk].t = Date.now(); }
}
// Canlı oranlar: bültende açık koşu 5 sn'de bir, diğer başlamamış koşular 20 sn'de bir
let _lastTouch = 0;
['touchstart','touchmove','pointerdown','scroll'].forEach(ev => document.addEventListener(ev, () => { _lastTouch = Date.now(); }, {passive: true}));
function schedulePatch(){
  if(schedulePatch.t) return;
  const go = () => {
    if(Date.now() - _lastTouch < 600){ schedulePatch.t = setTimeout(go, 400); return; }   // kaydırma/dokunma bitince uygula
    schedulePatch.t = 0;
    requestAnimationFrame(() => { if(!patchOranlar()) softRefresh(); });
  };
  schedulePatch.t = setTimeout(go, 0);
}
function oranDegisti(degisen){
  // degisen: [[sehir, kosuNo], ...]
  if(!degisen.length) return;
  if(visible() === 'bulten'){
    const bu = degisen.some(([c, r]) => c === city && r === race);
    const digerleri = degisen.some(([c, r]) => !(c === city && r === race));
    if(bu) schedulePatch();
    if(digerleri && selList().length) softRefresh();   // taslak kupondaki tahmini kazanç değişebilir
  } else softRefresh();
}
async function refreshOranlar(force, hizli){
  const key = hizli ? 'h' : 'y';
  const st = refreshOranlar[key] = refreshOranlar[key] || {};
  if(st.busy || BUL.note || !CITIES.length) return;
  const now = Date.now(), aralik = hizli ? 5000 : 20000;
  if(!force && now - (st.t || 0) < aralik) return;
  const iso = viewIso;
  let hedefler;   // [[şehir, [koşular]]]
  if(hizli){
    if(visible() !== 'bulten' || !city || raceDone(city, race)) return;
    const k = raceInfo(city, race); if(!k) return;
    hedefler = [[city, [k]]];
  } else {
    const cs = new Set([city]);
    posts.forEach(p => { if(p.coupon && p.coupon.city && (!p.coupon.iso || p.coupon.iso === iso)) cs.add(p.coupon.city); });
    hedefler = [...cs].filter(c => raceList(c).length).map(c => [c, raceList(c).filter(k => !raceDone(c, +k.no))]).filter(x => x[1].length);
  }
  st.t = now; st.busy = true;
  const degisen = [];
  try{
    for(const [c, kos] of hedefler){
      try{
        const r = await TJK.oranlariGetir(c, kos, iso, hizli ? 3000 : 15000);
        if(iso !== viewIso) break;   // tarih değişti
        BUL.live[c] = BUL.live[c] || {};
        Object.keys(r).forEach(no => { if(JSON.stringify(BUL.live[c][no]) !== JSON.stringify(r[no])){ BUL.live[c][no] = r[no]; degisen.push([c, +no]); } });
      }catch(e){}
    }
  } finally { st.busy = false; }
  oranDegisti(degisen);
}
let _doneSig = '';
